   "summary": "公众号开始内测「原创精选」，首批用户叫伯乐：每天可举荐 3 篇，7 天内的原创才行；72 小时内超过六成同行认可，才算入选。被选中的文章拿到付费加热，举荐的人也跟着分到推流。 近日，有人陆续收到了微信公众号官方发送的伯乐邀请。 邀请你成为「原创精选」的伯乐。 有人是在公众号后台收到的通知。 有人是在微信上，收到微信公众号平台服务号的邀请。 通过邀请可以看到。 微信公众号正在内测一个叫做「原创精选」的功能。 首批邀请使用这个功能的用户，就是伯乐。 伯乐，在这里，就是精选内容推荐官的意思。 1 接受邀请，成为伯乐 点击「查看详情」，进入邀请页，可点击确定来接受邀请。 接受邀请后，你就成为微信公众号",
