   "summary": "社区店八成生意藏在两公里内，可很多老板只盯着线上投放。两个几乎不花钱的动作：把周边小区、地铁口、学校医院逐个摸排再精准铺物料，把门头当成最大的广告位重做一遍，让路人变成顾客。 很多餐饮门店都在抱怨线上获客贵，线下获客难。线下获客确认不便宜，但线下获客不一定难。 我个人就想到了2种低成本线下获客途径，这些途径来自于我的日常观察和市井(非正式)调研，主要适用于街边店(社区店)，请知悉。 1 社区(小区)获客 我在之前的文章《餐饮门店极简选址及客流量(捕获率)测算方法》中有分享过1个观点：社区店/街边店的辐射范围基本在门店周边2公里。 这并不意味着顾客不会去2公里之外的地方吃饭，只是说相对概率较低，",
