   "summary": "大模型的算力成本，最终由推理框架这一中间层决定。DeepSeek 将内部推理框架 DeepInfer 全面开源，连同生产级编解码组件，把大规模部署的吞吐、延迟与能耗优化经验交给社区。这不仅是技术开放，更是一次降低 AI 使用门槛、推动普惠的产业信号。 大模型的能力边界由模型本身划定，但如何以合理成本提供超大规模的模型服务，还取决于一个长期未被公众了解的中间层：推理框架。 训练使模型学有所成，推理则让模型为人所用。面对如今海量的用户调用，推理框架负责统筹调度庞大的算力集群，其效率直接决定了 AI 服务的算力成本与电力消耗。 DeepSeek 长期致力于将推理性能推向极致。在此前开源一系列大模型、",
