   "id": "1nb3kog",
   "title": "斯坦福新课直接讲 personal agent，Grok Bot 工程师分享如何打造出 always-on agent",
   "url": "https://www.woshipm.com/ai/6481263.html",
   "summary": "合上笔记本，AI 编程助手就停了。Lee Robinson 在斯坦福 CS146S 讲 Grok Bot 这类 always-on agent 怎么搭：服务器、沙箱、记忆与动态工具发现，把一切当成一台长期在线的电脑，只在真正需要判断时才来打扰你。 你有没有想过，我们现在用的 AI 编程助手，其实有一个很大的软肋：你一合上笔记本电脑，它就停了。它只会在你发消息的时候才动一下，你不说话，它就不存在。那如果有一种 agent（智能体），像一个同事一样一直在线，会自己在后台干活，只有真正重要的时候才来找你，它背后到底是怎么搭起来的？ 这是 Lee Robinson 在斯坦福 CS146S 这门课上的一",
   "date": "2026-10-20T07:47:36.000Z",
