   "summary": "過去幾週，資安公司 NorForge 首席威脅研究員 Snorre Fagerland 從旁看著一名使用中文的駭客，攻破 100 多家企業的網站，包括農機製造商 Deere、家電公司 SharkNinja 與引擎製造商 Cummins。然而，這名駭客幾乎沒有親自動手，而是把這波攻擊近乎全數交給 AI 代理（AI Agent），讓代理花上數小時自主探測、入侵目標網站。 這是《Reuters》美國時間 10 月 19 日的獨家報導，素材來自 NorForge 同日公布的研究報告。Fagerland 認為，這次發現是真實世界的證據，顯示市售 AI 代理能在沒有人介入的情況下，從頭到尾完成複雜的入侵，",
