   "title": "产品经理需要了解的一些项目管理知识",
   "url": "https://www.woshipm.com/share/6480290.html",
   "summary": "业务要加需求，开发说没时间，产品经理夹在中间两头受气。这不是靠沟通技巧能解决的，而是项目管理的基本功问题。本文从范围管理、进度资源、变更管理、风险沟通四个维度，拆解产品经理如何用项目管理的底层逻辑，在现实约束下找到可执行的解决方案。 前几天带的一个新员工问我，有个项目最开始就跟业务定了范围，计划11月初上线。但是随着业务的发展，原先的方案已经无法实现完整的业务闭环，业务希望能在一期里面加入新的内容，但开发一口咬定说加不了，她现在夹在中间不知道怎么办了。 这是个非常典型的产品经理项目管理问题。做产品的应该多多少少都碰到过。 现实情况是，业务那边确实需要修改边界，开发这边也确实是没时间。 产品经理",
