   "id": "1obnr85",
   "title": "本地生活深度思考26",
   "url": "https://www.woshipm.com/share/6480422.html",
   "summary": "平台能把无数小商家的成交加总，单个商家却无法靠市场繁荣支付经营成本。本文分析本地生活供给过剩之后，稀缺性如何从供给转向需求分配，以及云连锁扩张怎样掩盖单店效率的下滑。 1/ 互联网把原本分散的供给与需求聚合到同一个市场，让大量小商家获得了线上交易的机会。对于平台，即使每家门店只贡献少量成交，只要聚合的商家足够多，就能形成庞大的交易规模。 但这里存在一个容易忽略的问题，平台可以把无数小商家的成交加起来，单个商家却无法依靠整个市场的繁荣来支付自己的经营成本。市场规模与个体收益之间，并不存在必然的增长关系。 2/ 本地生活的特殊性，在于需求受到地理半径、人口密度和消费频次的约束。互联网提高了需求匹配",
